    internal static readonly JavaScriptSerializer Json=new JavaScriptSerializer { MaxJsonLength=Int32.MaxValue,RecursionLimit=256 };
    internal static Dictionary<string,object> Obj(object o){return (Dictionary<string,object>)o;}
    internal static object[] Arr(object o){return ((IEnumerable)o).Cast<object>().ToArray();}
    internal static string Hash(byte[] bytes){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();}
    internal static string HashFile(string file){using(var s=File.OpenRead(file))using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(s)).Replace("-","").ToLowerInvariant();}
