        public void Dispose(){if(stream!=null)stream.Dispose();}
    }
    static Dictionary<string,object> Integrity(byte[] bytes){const int block=4*1024*1024;var hashes=new List<string>();for(int i=0;i<bytes.Length;i+=block){var b=new byte[Math.Min(block,bytes.Length-i)];Buffer.BlockCopy(bytes,i,b,0,b.Length);hashes.Add(Hash(b));}return new Dictionary<string,object>{{"algorithm","SHA256"},{"hash",Hash(bytes)},{"blockSize",block},{"blocks",hashes}};}
    static byte[] Policy(byte[] input){var text=Encoding.UTF8.GetString(input);text=Regex.Replace(text,@"<!-- HYDRA_NEXUS_MEDIA_CSP_V1:([A-Za-z0-9+/=]+) --><meta\b[^>]*>",m=>Encoding.UTF8.GetString(Convert.FromBase64String(m.Groups[1].Value)),RegexOptions.IgnoreCase);var matches=Regex.Matches(text,"<meta\\b(?=[^>]*\\bhttp-equiv=[\"']Content-Security-Policy[\"'])[^>]*>",RegexOptions.IgnoreCase);if(matches.Count!=1)throw new IOException("Unsupported Hydra media policy.");var meta=matches[0];var attr=Regex.Match(meta.Value,"\\bcontent=([\"'])(.*?)\\1",RegexOptions.IgnoreCase);if(!attr.Success)throw new IOException("Unsupported Hydra policy attribute.");var policy=attr.Groups[2].Value;var media=Regex.Match(policy,@"(?:^|;)\s*media-src\s+([^;]*)",RegexOptions.IgnoreCase);if(media.Success){var values=media.Groups[1];if(!values.Value.Split((char[])null,StringSplitOptions.RemoveEmptyEntries).Contains("nexus-media:"))policy=policy.Substring(0,values.Index)+values.Value.Replace("'none'","").Trim()+" nexus-media:"+policy.Substring(values.Index+values.Length);}else{var def=Regex.Match(policy,@"(?:^|;)\s*default-src\s+([^;]*)",RegexOptions.IgnoreCase);if(!def.Success)throw new IOException("Unsupported Hydra policy default.");policy=policy.TrimEnd().TrimEnd(';')+"; media-src "+def.Groups[1].Value.Replace("'none'","").Trim()+" nexus-media:;";}var at=attr.Groups[2];var patched="<!-- HYDRA_NEXUS_MEDIA_CSP_V1:"+Convert.ToBase64String(Encoding.UTF8.GetBytes(meta.Value))+" -->"+meta.Value.Substring(0,at.Index)+policy+meta.Value.Substring(at.Index+at.Length);return Encoding.UTF8.GetBytes(text.Substring(0,meta.Index)+patched+text.Substring(meta.Index+meta.Length));}
    internal static int Fuse(byte[] bytes){var marker=Encoding.ASCII.GetBytes("dL7pKGdnNz796PbbjQWNKmHXBZaB9tsX");for(int i=0;i<=bytes.Length-marker.Length-2;i++){if(bytes[i]!=marker[0])continue;bool match=true;for(int j=1;j<marker.Length;j++)if(bytes[i+j]!=marker[j]){match=false;break;}if(!match)continue;int start=i+marker.Length+2,count=bytes[start-1];if(bytes[start-2]!=1||count<6||count>bytes.Length-start||!new byte[]{48,49}.Contains(bytes[start+4]))throw new IOException("Unsupported Electron integrity settings.");return start+4;}throw new IOException("Electron integrity settings not found.");}
    internal static bool Running(string directory){foreach(var p in Process.GetProcessesByName("Hydra").Concat(Process.GetProcessesByName("hydralauncher"))){using(p){try{if(Path.GetFullPath(p.MainModule.FileName).Equals(Path.Combine(directory,"Hydra.exe"),StringComparison.OrdinalIgnoreCase))return true;}catch{return true;}}}return false;}
    static void Exclusive(string path){var deadline=DateTime.UtcNow.AddSeconds(20);while(true){try{using(File.Open(path,FileMode.Open,FileAccess.ReadWrite,FileShare.None)){}return;}catch(IOException e){var code=e.HResult&65535;if((code!=32&&code!=33)||DateTime.UtcNow>=deadline)throw;System.Threading.Thread.Sleep(200);}}}
