        var token=Guid.NewGuid().ToString("N");var temporary=archive+".nexus-"+token+".tmp";var exeTemp=exe+".nexus-"+token+".tmp";var recovery=Path.Combine(directory,"resources","nexus-native-recovery",token);var committed=false;string beforeArchive=null,beforeExe=null;bool archiveChanged=false,exeChanged=false;
        try{
