            // Verify exclusive access immediately before replacing either live file.
            checkCancel();Exclusive(exe);Exclusive(archive);
            if(Running(directory))throw new IOException("Hydra was reopened. Installation cancelled.");
            if(HashFile(archive)!=beforeArchive||HashFile(exe)!=beforeExe)throw new IOException("Hydra changed while waiting for file access.");
