    }
    static void Restore(string source,string dest,string expected){if(HashFile(source)!=expected)throw new IOException("Recovery copy changed; installation requires manual recovery.");var tmp=dest+".restore-"+Guid.NewGuid().ToString("N");File.Copy(source,tmp);File.Replace(tmp,dest,null);if(HashFile(dest)!=expected)throw new IOException("Recovery verification failed.");}
}
